package main

import (
 "fmt"
 "os"
 "os/exec"
 "path/filepath"
 "strings"
 "gopkg.in/yaml.v3"
)

func main() {
 root, _ := os.Getwd()
 scratch := filepath.Join(root,".temp/BUG-261018-bisu6n")
 binary := filepath.Join(scratch,"ciworkflow.test")
 raw, err := os.ReadFile(filepath.Join(root,".github/workflows/ci.yml")); must(err)
 var base map[string]any; must(yaml.Unmarshal(raw,&base))
 cmd := exec.Command(binary,"-test.run=^TestLinuxCIWorkflowTemporaryTreeRestore$","-test.v")
 cmd.Dir=filepath.Join(root,"tools/ciworkflow")
 out, err := cmd.CombinedOutput(); must(err)
 if !strings.Contains(string(out),"--- PASS: TestLinuxCIWorkflowTemporaryTreeRestore") { panic("positive control not applied") }
 fmt.Println("original: exit 0, named gate green")
 count:=0
 jobs:=base["jobs"].(map[string]any)
 for name, value := range jobs {
  job:=value.(map[string]any)
  route:=fmt.Sprint(job["runs-on"])
  if !strings.Contains(route,"LINUX_SELF_HOSTED") && !strings.Contains(route,"relux-linux") { continue }
  for _, plant:=range []string{"remove","echo","success-only","hosted","not-final","blocking","wrong-shell"} {
   var wf map[string]any; must(yaml.Unmarshal(raw,&wf))
   j:=wf["jobs"].(map[string]any)[name].(map[string]any)
   steps:=j["steps"].([]any); n:=len(steps)-1; last:=steps[n].(map[string]any)
   switch plant {
   case "remove": steps=steps[:n]
   case "echo": last["run"]="echo 'bash scripts/restore-runner-tmp.sh'"
   case "success-only": last["if"]=strings.Replace(fmt.Sprint(last["if"]),"always()","success()",1)
   case "hosted": last["if"]=strings.Replace(fmt.Sprint(last["if"]),"self-hosted","github-hosted",1)
   case "not-final": steps=append(steps,map[string]any{"run":"echo later"})
   case "blocking": last["continue-on-error"]=false
   case "wrong-shell": last["shell"]="sh"
   }
   j["steps"]=steps
   data,err:=yaml.Marshal(wf);must(err)
   path:=filepath.Join(scratch,"workflow-"+name+"-"+plant+".yml");must(os.WriteFile(path,data,0600))
   cmd:=exec.Command(binary,"-test.run=^TestLinuxCIWorkflowTemporaryTreeRestore$","-test.v")
   cmd.Dir=filepath.Join(root,"tools/ciworkflow")
   cmd.Env=append(os.Environ(),"CI_WORKFLOW_UNDER_TEST="+path)
   out,err:=cmd.CombinedOutput()
   exit,ok:=err.(*exec.ExitError)
   must(os.WriteFile(strings.TrimSuffix(path,".yml")+".log",out,0600))
   if !ok || exit.ExitCode()!=1 || !strings.Contains(string(out),"--- FAIL: TestLinuxCIWorkflowTemporaryTreeRestore") || !strings.Contains(string(out),name+": missing") { panic(fmt.Sprintf("survivor or unrelated failure %s/%s: %v %s",name,plant,err,out)) }
   fmt.Printf("%s/%s: exit 1 expected red; TestLinuxCIWorkflowTemporaryTreeRestore\n",name,plant); count++
  }
 }
 if count!=49 { panic(fmt.Sprintf("plant count=%d",count)) }
 fmt.Println("49 of 49 plants killed by named gate; 0 survivors")
}
func must(err error) { if err!=nil { panic(err) } }
